query:
-- Get Romero project ID
SET @romero_id = (SELECT id FROM projects WHERE title = 'Romero' LIMIT 1);

-- Add tags for Romero
INSERT INTO projectTags (projectId, tagId)
SELECT @romero_id, id FROM tags WHERE name IN ('World Premiere', '2024', 'Political Drama', 'Religious Themes', 'Biographical', 'University Theatre')
ON DUPLICATE KEY UPDATE projectId = projectId;

